const $ = (q, root=document) => root.querySelector(q);
const $$ = (q, root=document) => [...root.querySelectorAll(q)];
const content = $('#content'), dialog = $('#modal');
let clients = [], currentPage = 'inicio', currentClient = null, protocolResult = null;
const moduleNames = { anthropometry:'Antropometria', posture:'Postural', physical:'Testes físicos' };
const protocols = {
  jp7:{label:'Jackson & Pollock 7',sites:['Peitoral','Axilar média','Tríceps','Subescapular','Abdominal','Supra-ilíaca','Coxa'],sex:['Masculino','Feminino'],note:'Densidade estimada; fórmula validada originalmente em adultos. Fora da faixa de referência, mostre aviso.'},
  petroski:{label:'Petroski 4',sites:{Masculino:['Subescapular','Tríceps','Supra-ilíaca','Panturrilha medial'],Feminino:['Axilar média','Supra-ilíaca','Coxa','Panturrilha medial']},sex:['Masculino','Feminino'],note:'Brasileiros adultos: homens 18–66; mulheres 18–51. Fórmula feminina usa log10.'},
  guedes:{label:'Guedes 3',sites:{Masculino:['Tríceps','Supra-ilíaca','Abdominal'],Feminino:['Subescapular','Supra-ilíaca','Coxa']},sex:['Masculino','Feminino'],note:'Universitários jovens. Estimativa fora da faixa original deve ser sinalizada.'},
  dw:{label:'Durnin & Womersley 4',sites:['Bíceps','Tríceps','Subescapular','Supra-ilíaca'],sex:['Masculino','Feminino'],note:'Adultos, equação por sexo e faixa etária; tabela começa aos 17 anos.'},
  slaughter:{label:'Slaughter 2',sites:['Tríceps','Subescapular'],sex:['Masculino','Feminino'],note:'Infantojuvenil. Requer estágio maturacional informado por profissional; origem e limites descritos no apêndice técnico.'},
  yuhasz:{label:'Yuhasz/Carter 6',sites:['Tríceps','Subescapular','Supraespinal','Abdominal','Coxa','Panturrilha medial'],sex:['Masculino','Feminino'],note:'Versão atleta. Equações diretas para o %G, sem densidade.'},
  faulkner:{label:'Faulkner 4',sites:['Tríceps','Subescapular','Supra-ilíaca','Abdominal'],sex:['Masculino','Feminino'],note:'Uso histórico em atletas; aplicabilidade fora da amostra original é limitada.'},
  isak8:{label:'Perfil ISAK Σ8',sites:['Bíceps','Tríceps','Subescapular','Crista ilíaca','Supraspinale','Abdominal','Coxa anterior','Panturrilha medial'],sex:['Masculino','Feminino'],note:'Somatório em mm; não calcula percentual de gordura.'}
};
const views=['Anterior','Posterior','Lateral direita','Lateral esquerda','Teste de Adam'];
let postureMarkers={},postureGridState={},posturePhotoDims={},postureLastPoint={};
const landmarkPairs={
  'Anterior':['Livre — D/E','Ombros — acrômios','Escápulas','Pelve — cristas ilíacas/EIAS','Cabeça — tragion D/E'],
  'Posterior':['Livre — D/E','Ombros — acrômios','Escápulas — ângulos inferiores','Pelve — cristas ilíacas','Cabeça — tragion D/E'],
  'Lateral direita':['Livre — D/E','Alinhamento vertical — tragion ao tornozelo'],
  'Lateral esquerda':['Livre — D/E','Alinhamento vertical — tragion ao tornozelo'],
  'Teste de Adam':['Livre — D/E']
};
const posturalFindings={
  'Anterior':['Cabeça inclinada','Ombro elevado','Assimetria clavicular','Assimetria de cintura','Pelve aparentemente inclinada','Joelho valgo aparente','Joelho varo aparente','Pé/tornozelo valgo','Pé/tornozelo varo'],
  'Posterior':['Escápula elevada','Escápula alada','Assimetria escapular','Desvio lateral aparente do tronco','Assimetria de cintura','Pelve assimétrica','Retropé valgo','Retropé varo'],
  'Lateral direita':['Cabeça anteriorizada','Ombro arredondado','Cifose torácica aparente','Lordose lombar aparente','Inclinação pélvica anterior','Inclinação pélvica posterior'],
  'Lateral esquerda':['Cabeça anteriorizada','Ombro arredondado','Cifose torácica aparente','Lordose lombar aparente','Inclinação pélvica anterior','Inclinação pélvica posterior'],
  'Teste de Adam':['Proeminência torácica','Proeminência lombar','Assimetria do tronco']
};
const tests=[
  ['1RM/RM submáxima','Força máxima','Exercício, carga e repetições. Estimativa depende da fórmula e faixa de repetições.', 'kg'],
  ['Handgrip','Força de preensão','Dinamômetro necessário. Registrar mão, tentativas e aparelho.', 'kgf'],
  ['Sentar e levantar — 30 s','Força funcional','Cadeira estável. Contar repetições completas em 30 segundos.', 'repetições'],
  ['Five Times Sit-to-Stand','Força funcional','Cadeira estável. Cronometrar cinco repetições completas.', 's'],
  ['Countermovement Jump (CMJ)','Potência','Tapete/plataforma ou método validado necessário para altura.', 'cm'],
  ['Salto horizontal parado','Potência','Fita/régua no chão necessária; medir da linha inicial até o contato mais próximo.', 'cm'],
  ['Cooper — 12 minutos','Aeróbio','Pista/percurso medido e cronômetro. VO₂ estimado pela distância.', 'm'],
  ['Rockport — 1 milha','Aeróbio','Percurso de 1 milha, tempo e FC final obrigatórios para estimativa.', 'min'],
  ['Caminhada de 6 minutos (TC6)','Aeróbio/funcional','Corredor de 30 m e cones. Registrar distância, pausas, sintomas e FC.', 'm'],
  ['Shuttle Run — 20 m','Aeróbio intermitente','Duas linhas a 20 m e áudio identificado (protocolo/versão).', 'estágio'],
  ['YMCA Step Test','Aeróbio submáximo','Degrau de 30,5 cm, metrônomo e FC de recuperação.', 'bpm'],
  ['YMCA Cycle Ergometer','Aeróbio submáximo','Cicloergômetro calibrado; carga e FC em cada estágio.', 'W'],
  ['Yo-Yo IR1 / IR2','Aeróbio intermitente','Campo 20 m, áudio específico; escolher IR1 ou IR2. Resultado primário é distância.', 'm']
].map((t,i)=>({id:`perf${i}`,name:t[0],group:t[1],how:t[2],unit:t[3]}));
const clinical=[
  ['Jobe / Empty Can','Ombro','Braços a ~90° no plano escapular, polegares para baixo; aplicar resistência descendente. Anotar dor e força.'],
  ['Full Can','Ombro','Elevação no plano escapular com polegares para cima; aplicar resistência descendente.'],
  ['Drop Arm','Ombro','Elevar braço passivamente e solicitar descida lenta controlada.'],
  ['External Rotation Lag Sign','Ombro','Colocar ombro em rotação externa passiva e pedir manutenção da posição.'],
  ['Rotação externa resistida','Ombro','Cotovelos junto ao tronco a 90°; resistir rotação externa isométrica.'],
  ['Patte','Ombro','Ombro abduzido a ~90°, cotovelo flexionado; resistir rotação externa.'],
  ['Hornblower','Ombro','Braço elevado e cotovelo flexionado; observar capacidade de manter rotação externa.'],
  ['Lift-off / Gerber','Ombro','Dorso da mão atrás da lombar; afastar ou manter afastada contra resistência.'],
  ['Belly Press / Napoleon','Ombro','Palma sobre abdome e cotovelo à frente; pressionar sem flexionar punho.'],
  ['Bear Hug','Ombro','Mão no ombro oposto, cotovelo anterior; avaliador tenta afastar a mão.'],
  ['Internal Rotation Lag','Ombro','Colocar mão atrás das costas e pedir que mantenha sem apoio.'],
  ['Belly-off','Ombro','Elevar a mão do abdome poucos centímetros e pedir para manter punho reto.'],
  ['Hawkins-Kennedy','Ombro','Ombro/cotovelo flexionados ~90°; aplicar rotação interna passiva controlada.'],
  ['Step-down','Joelho','Descer de degrau de altura registrada; observar alinhamento, equilíbrio e dor.'],
  ['Thessaly','Joelho','Apoio unipodal com joelho ~20°; rotação controlada do corpo. Não fazer se inseguro.'],
  ['McMurray','Joelho','Flexionar joelho, aplicar rotação tibial/estresse e estender gradualmente.'],
  ['Lachman','Joelho','Joelho ~20–30°; estabilizar fêmur e transladar tíbia anteriormente.'],
  ['FABER / Patrick','Quadril','Supino, quadril em flexão-abdução-rotação externa; registrar local da dor.'],
  ['FADIR','Quadril','Supino, flexionar, aduzir e rodar internamente o quadril de forma controlada.'],
  ['Thomas','Quadril','Supino na borda; levar um joelho ao peito e observar coxa contralateral.'],
  ['Trendelenburg','Quadril','Apoio unipodal até 30 s; observar queda da pelve contralateral.'],
  ['Phalen','Punho/mão','Dorsos das mãos aproximados, punhos em flexão; registrar parestesia e latência.'],
  ['Finkelstein','Punho/mão','Polegar dentro da palma e desvio ulnar controlado; registrar dor radial.'],
  ['Cozen','Cotovelo','Antebraço pronado, punho estendido; resistir extensão e registrar dor lateral.'],
  ['Mill','Cotovelo','Cotovelo estendido; alongar flexores do punho de forma controlada.'],
  ['Lasègue / SLR','Coluna','Supino; elevar perna com joelho estendido e registrar ângulo/sintoma irradiado.'],
  ['Slump','Coluna','Sentado; flexão gradual de tronco/cervical com extensão de joelho e dorsiflexão.'],
  ['Elevação ativa da perna estendida','Coluna','Supino; elevar perna ativamente e observar controle lombo-pélvico.'],
  ['Movimentos repetidos lombares','Coluna','Repetir flexão/extensão em amplitude tolerada; observar resposta dos sintomas.'],
  ['Mobilidade cervical ativa','Coluna','Flexão, extensão e rotação ativas; medir amplitude/dor por direção.']
].map((t,i)=>({id:`clin${i}`,name:t[0],group:t[1],how:t[2],unit:'Achado'}));

const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateToday = () => new Date().toISOString().slice(0,10);
const initials = name => String(name||'?').trim().split(/\s+/).slice(0,2).map(p=>p[0]).join('').toUpperCase();
const ageOn = (birth,date) => { if(!birth)return null; const b=new Date(`${birth}T00:00:00`), d=new Date(`${date}T00:00:00`); let a=d.getFullYear()-b.getFullYear(); if(d.getMonth()<b.getMonth()||(d.getMonth()===b.getMonth()&&d.getDate()<b.getDate()))a--; return a; };
const fmtDate = d => d ? new Date(`${d}T00:00:00`).toLocaleDateString('pt-BR') : 'Sem avaliação';
async function api(path,options={}){const r=await fetch(path,{headers:{'content-type':'application/json'},...options});const data=await r.json();if(r.status===401){window.location.assign('/');throw new Error(data.error||'Entre novamente.')}if(!r.ok)throw new Error(data.error||'Falha ao salvar.');return data}
async function loadClients(){clients=await api('/api/clients');$('#nav-count').textContent=clients.length;}
function showToast(message){const t=$('#toast');t.textContent=message;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2800)}
function setNav(page,title,crumb='ESPAÇO DE TRABALHO'){currentPage=page;$('#page-title').textContent=title;$('#breadcrumb').textContent=crumb;$$('.nav-item[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));}
function renderHome(){setNav('inicio','Visão geral');content.innerHTML=`<div class="hero"><section class="hero-card"><div class="eyebrow">AVALIAÇÃO COM MAIS CLAREZA</div><h2>Um histórico melhor começa com uma boa medida.</h2><p>Organize medidas, postura e testes físicos em um só lugar.</p><button class="button" id="hero-new">＋ Criar aluno e avaliar</button></section><section class="stat-card"><div><div class="stat-label">ALUNOS CADASTRADOS</div><div class="stat-big">${clients.length}</div></div><div class="stat-foot">Os registros ficam no banco do servidor em que o sistema está rodando.</div></section></div><div class="section-heading"><div><h2>Alunos recentes</h2><p>Abra um perfil para acompanhar as avaliações.</p></div><button class="button button-link" id="see-all">Ver todos →</button></div>${clientGrid(clients.slice(0,6))}`;$('#hero-new').onclick=()=>openClientModal(true);$('#quick-new').onclick=()=>openClientModal(false);$('#see-all').onclick=()=>renderClients();bindClientCards();}
function clientGrid(list){if(!list.length)return `<div class="empty"><strong>Seu espaço está pronto.</strong>Cadastre o primeiro aluno para criar uma avaliação.<div style="margin-top:14px"><button class="button button-primary" id="empty-new">＋ Novo aluno</button></div></div>`;return `<div class="client-grid">${list.map(c=>`<article class="client-card" data-client="${c.id}" tabindex="0"><div class="client-top"><div class="avatar">${esc(initials(c.name))}</div><div><div class="client-name">${esc(c.name)}</div><div class="client-sub">${c.birth_date?`${ageOn(c.birth_date,dateToday())} anos`:'Idade não informada'}${c.sex?` · ${c.sex}`:''}</div></div></div><div class="client-meta"><span><strong>${c.evaluation_count||0}</strong> avaliações</span><span>${c.last_evaluation?fmtDate(c.last_evaluation):'Sem histórico'}</span></div></article>`).join('')}</div>`}
function bindClientCards(){ $$('.client-card').forEach(card=>{const go=()=>openProfile(Number(card.dataset.client));card.onclick=go;card.onkeydown=e=>{if(e.key==='Enter')go()}});const b=$('#empty-new');if(b)b.onclick=()=>openClientModal(true); }
async function openClientModal(startEval=false){dialog.innerHTML=`<div class="modal-inner"><div class="modal-head"><div><h2>Novo aluno</h2><p>Nome é o único campo obrigatório nesta etapa.</p></div><button class="icon-button" data-close aria-label="Fechar">×</button></div><form id="client-form"><div class="form-grid"><div class="field full"><label for="c-name">Nome completo *</label><input class="input" id="c-name" name="name" required autocomplete="name" placeholder="Ex.: Ana Souza"></div><div class="field"><label for="c-birth">Data de nascimento</label><input class="input" type="date" id="c-birth" name="birth_date"></div><div class="field"><label for="c-sex">Sexo para equações</label><select id="c-sex" name="sex"><option value="">Não informado</option><option>Masculino</option><option>Feminino</option></select></div><div class="field full"><label for="c-phone">Telefone (opcional)</label><input class="input" id="c-phone" name="phone" placeholder="(00) 00000-0000"></div></div><div class="modal-actions"><button class="button button-secondary" type="button" data-close>Cancelar</button><button class="button button-primary">Salvar aluno</button></div></form></div>`;dialog.showModal();$$('[data-close]',dialog).forEach(b=>b.onclick=()=>dialog.close());$('#client-form').onsubmit=async e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.currentTarget));try{const c=await api('/api/clients',{method:'POST',body:JSON.stringify(v)});dialog.close();await loadClients();showToast('Aluno cadastrado.');if(startEval)openEvaluation(c.id);else openProfile(c.id)}catch(err){showToast(err.message)}};setTimeout(()=>$('#c-name')?.focus(),30)}
async function openProfile(id){
  currentClient=await api(`/api/clients/${id}`);
  setNav('alunos',currentClient.name,'PERFIL DO ALUNO');
  const evals=currentClient.evaluations||[], timeline=evals.slice().sort((a,b)=>a.evaluated_on.localeCompare(b.evaluated_on)||a.id-b.id);
  content.innerHTML=`<div class="page-row" style="justify-content:space-between;margin-bottom:20px"><div class="client-top"><div class="avatar" style="width:48px;height:48px">${esc(initials(currentClient.name))}</div><div><div class="client-name" style="font-size:17px">${esc(currentClient.name)}</div><div class="client-sub">${currentClient.birth_date?`${ageOn(currentClient.birth_date,dateToday())} anos · Nascimento ${fmtDate(currentClient.birth_date)}`:'Data de nascimento não informada'}${currentClient.sex?` · ${currentClient.sex}`:''}</div></div></div><button class="button button-primary" id="new-eval">＋ Nova avaliação</button></div><div class="two-col"><section class="panel"><div class="section-heading" style="margin:0 0 7px"><div><h2>Histórico de avaliações</h2><p>As anteriores ficam salvas. Marque uma ou mais para comparar ou exportar.</p></div><span class="badge">${evals.length} registros</span></div>${evals.length?`<div class="history-actions no-print"><button class="button button-secondary" id="latest-compare" ${evals.length<2?'disabled':''}>Comparar últimas duas</button><button class="button button-secondary" id="selected-compare">Comparar selecionadas</button><button class="button button-primary" id="all-report">Exportar selecionadas em PDF</button></div>${evals.map(e=>{const n=timeline.findIndex(x=>x.id===e.id)+1;return `<div class="evaluation-row"><label style="display:flex;gap:9px;align-items:flex-start"><input class="report-check" type="checkbox" value="${e.id}" checked style="accent-color:var(--teal);margin-top:2px"><span><span class="eval-date">${fmtDate(e.evaluated_on)}</span><span class="eval-desc">${n}ª avaliação${n===timeline.length?' · mais recente':''} · ${e.modules.map(m=>moduleNames[m]||m).join(' · ')}</span></span></label><button class="button button-link button-sm" data-report="${e.id}">Abrir →</button></div>`}).join('')}`:`<div class="empty" style="margin-top:12px"><strong>Nenhuma avaliação ainda.</strong>Inicie pelo módulo que fizer sentido para este aluno.</div>`}</section><aside class="panel"><div class="panel-title">Resumo do cadastro</div><div class="field"><span class="field-label">Telefone opcional</span><span style="font-size:12px">${esc(currentClient.phone||'Não informado')}</span></div><div class="divider"></div><div class="notice notice-green">A data e cada avaliação permanecem no histórico. Fotos e sinais vitais são opcionais.</div><div class="subheading">Comparação</div><p class="help">Compare as duas últimas rapidamente ou marque várias datas. O relatório mostra medidas disponíveis, evolução e variação entre a primeira e a última seleção.</p></aside></div>`;
  $('#quick-new').onclick=()=>openClientModal(false);$('#new-eval').onclick=()=>openEvaluation(id);
  const selected=()=>evals.filter(e=>$$('.report-check').some(ch=>ch.checked&&Number(ch.value)===e.id));
  $('#all-report')?.addEventListener('click',()=>openReport(selected()));
  $('#selected-compare')?.addEventListener('click',()=>openComparison(selected()));
  $('#latest-compare')?.addEventListener('click',()=>openComparison(timeline.slice(-2)));
  $$('[data-report]').forEach(b=>b.onclick=()=>openReport(evals.filter(e=>e.id===Number(b.dataset.report))));
}
function openEvaluation(id){currentClient=clients.find(c=>c.id===id)||currentClient;if(!currentClient){openProfile(id);return}protocolResult=null;postureMarkers={};postureGridState={};posturePhotoDims={};postureLastPoint={};setNav('alunos','Nova avaliação',`AVALIAÇÃO · ${currentClient.name.toUpperCase()}`);content.innerHTML=evalForm(currentClient);$('#quick-new').onclick=()=>openClientModal(false);bindEvaluationForm();}
function evalForm(c){const age=c.birth_date?ageOn(c.birth_date,dateToday()):'';return `<form id="evaluation-form" data-client="${c.id}"><div class="panel"><div class="page-row" style="justify-content:space-between"><div><div class="small-caps">NOVA AVALIAÇÃO</div><div class="panel-title" style="margin:5px 0 0">${esc(c.name)} <span class="client-sub">${age!==''?`· ${age} anos`:''}</span></div></div><div class="field" style="width:160px"><label for="eval-date">Data da avaliação</label><input class="input" id="eval-date" name="evaluated_on" type="date" value="${dateToday()}" required></div></div><div class="subheading">Escolha os módulos</div><div class="module-grid">${[['anthropometry','◉','Antropometria','Medidas, perímetros e dobras.'],['posture','⌁','Postural','Vistas, simetógrafo e checklist.'],['physical','↗','Testes físicos','Capacidade, força e função.']].map(([id,icon,title,desc])=>`<label class="module-choice"><input type="checkbox" name="module" value="${id}" data-module><span class="module-card"><span class="module-icon">${icon}</span><strong>${title}</strong><small>${desc}</small></span></label>`).join('')}</div><div class="field" style="margin-top:13px"><label class="check-row" style="width:max-content"><input type="checkbox" id="complete-toggle"><span>Avaliação completa — selecionar os três módulos</span></label></div><div class="divider"></div><div class="field"><label class="check-row" style="width:max-content"><input type="checkbox" id="vitals-toggle"><span>Adicionar sinais vitais em repouso (opcional)</span></label><small>Pode pular esta etapa tranquilamente.</small></div><div id="vitals-fields" class="form-grid" hidden style="margin-top:10px"><div class="field"><label>Pressão arterial sistólica</label><input class="input" name="bp_sys" inputmode="numeric" placeholder="mmHg"></div><div class="field"><label>Pressão arterial diastólica</label><input class="input" name="bp_dia" inputmode="numeric" placeholder="mmHg"></div><div class="field"><label>Frequência cardíaca em repouso</label><input class="input" name="rest_hr" inputmode="numeric" placeholder="bpm"></div></div></div><div id="module-sections"></div><div class="page-row" style="justify-content:space-between;margin-top:18px"><button type="button" class="button button-secondary" id="cancel-eval">Cancelar</button><button class="button button-primary">Salvar avaliação</button></div></form>`}
function bindEvaluationForm(){const form=$('#evaluation-form');$$('[data-module]',form).forEach(el=>el.onchange=renderModuleSections);$('#complete-toggle').onchange=e=>{$$('[data-module]',form).forEach(x=>x.checked=e.target.checked);renderModuleSections()};$('#vitals-toggle').onchange=e=>$('#vitals-fields').hidden=!e.target.checked;$('#cancel-eval').onclick=()=>openProfile(Number(form.dataset.client));form.onsubmit=saveEvaluation;}
function renderModuleSections(){const chosen=$$('[data-module]:checked').map(x=>x.value), host=$('#module-sections');host.innerHTML=chosen.map(m=>m==='anthropometry'?anthroSection():m==='posture'?postureSection():physicalSection()).join('');wireAnthro();wirePhotos();}
function anthroSection(){
  const perimeters=[
    ['arm_relaxed_right','Braço direito relaxado'],['arm_contracted_right','Braço direito contraído'],
    ['arm_relaxed_left','Braço esquerdo relaxado'],['arm_contracted_left','Braço esquerdo contraído'],
    ['shoulders','Ombros'],['chest','Peito / tórax'],['waist','Cintura'],['abdomen','Abdômen'],['hip','Quadril'],
    ['thigh_medial_right','Coxa medial direita'],['thigh_medial_left','Coxa medial esquerda'],
    ['thigh_contracted_right','Coxa contraída direita'],['thigh_contracted_left','Coxa contraída esquerda'],
    ['calf_right','Panturrilha direita'],['calf_left','Panturrilha esquerda'],
    ['forearm_right','Antebraço direito'],['forearm_left','Antebraço esquerdo'],['neck','Pescoço']
  ];
  return `<section class="panel module-section"><div class="page-row" style="justify-content:space-between"><div><div class="small-caps">MÓDULO 01</div><div class="panel-title" style="margin:4px 0">Antropometria e adipometria</div></div><span class="badge">medidas brutas + estimativas</span></div><div class="form-grid"><div class="field"><label>Peso corporal</label><input class="input" name="weight" type="number" step="0.1" placeholder="kg"></div><div class="field"><label>Estatura</label><input class="input" name="height" type="number" step="0.1" placeholder="cm"></div></div><div class="result-box" id="bmi-result"><div><span class="field-label">IMC</span><small>Calculado a partir de peso e estatura</small></div><strong>—</strong></div><div class="subheading">Dobras cutâneas</div><div class="form-grid"><div class="field"><label for="protocol">Protocolo</label><select class="input" id="protocol" name="protocol"><option value="">Selecione</option>${Object.entries(protocols).map(([k,p])=>`<option value="${k}">${p.label}</option>`).join('')}</select></div></div><div class="protocol-fields" id="skinfold-fields"></div><div class="notice" id="protocol-note" style="margin-top:12px">Selecione um protocolo para ver os sítios e a elegibilidade.</div><div class="result-box" id="fat-result" hidden><div><span class="field-label">Resultado estimado</span><small id="fat-label"></small></div><strong id="fat-value">—</strong></div><div class="subheading">Perímetros corporais (cm)</div><div class="form-grid">${perimeters.map(([name,label])=>`<div class="field"><label>${label}</label><input class="input" name="${name}" type="number" min="0" step="0.1" placeholder="cm"></div>`).join('')}</div><div class="subheading">Diâmetros ósseos (cm)</div><div class="form-grid"><div class="field"><label>Diâmetro biepicondilar do úmero</label><input class="input" name="humerus_diameter" type="number" min="0" step="0.1" placeholder="cm"></div><div class="field"><label>Diâmetro biepicondilar do fêmur</label><input class="input" name="femur_diameter" type="number" min="0" step="0.1" placeholder="cm"></div></div><div class="field" style="margin-top:12px"><label>Observações antropométricas</label><textarea class="input" name="anthro_notes" rows="2" placeholder="Método, instrumento, condições de coleta…"></textarea></div></section>`;
}
function wireAnthro(){const protocol=$('#protocol');if(!protocol)return;const form=$('#evaluation-form');const recalc=()=>{const w=parseFloat(form.elements.weight.value),h=parseFloat(form.elements.height.value);const box=$('#bmi-result');box.querySelector('strong').textContent=w>0&&h>0?(w/((h/100)**2)).toFixed(1)+' kg/m²':'—';};form.elements.weight.oninput=recalc;form.elements.height.oninput=recalc;protocol.onchange=renderProtocol;form.elements.sex?.addEventListener?.('change',renderProtocol);renderProtocol();}
function renderProtocol(){
  const form=$('#evaluation-form'), key=$('#protocol')?.value, def=protocols[key], host=$('#skinfold-fields');
  if(!host)return;
  const sex=currentClient.sex||'';
  if(!def){host.innerHTML='';$('#protocol-note').textContent='Selecione um protocolo para ver os sítios e a elegibilidade.';$('#fat-result').hidden=true;return}
  let variant='subscapular';
  if(key==='slaughter')host.innerHTML=`<div class="field full"><label>Variante Slaughter</label><select class="input" name="slaughter_variant"><option value="subscapular">Tríceps + subescapular</option><option value="calf">Tríceps + panturrilha medial</option></select></div><div class="field"><label>Estágio maturacional informado pelo profissional</label><select class="input" name="maturation"><option value="">Selecionar</option><option value="pre">Pré-púbere (Tanner I–II)</option><option value="pub">Púbere (Tanner III)</option><option value="post">Pós-púbere (Tanner IV–V)</option></select></div><div class="field"><label>Categoria da amostra original (meninos, ramo ≤35 mm)</label><select class="input" name="slaughter_group"><option value="">Não informada</option><option value="white">Branco (tabela original)</option><option value="black">Negro (tabela original)</option></select></div>`;
  const getSites=()=>key==='slaughter'&&form.elements.slaughter_variant?.value==='calf'?['Tríceps','Panturrilha medial']:(Array.isArray(def.sites)?def.sites:(def.sites[sex]||def.sites.Masculino));
  const drawSites=()=>{const sites=getSites();variant=form.elements.slaughter_variant?.value||'subscapular';const controls=key==='slaughter'?host.innerHTML.slice(0,host.innerHTML.indexOf('</div>')+6):'';const prefix=key==='slaughter'?`<div class="field full"><label>Variante Slaughter</label><select class="input" name="slaughter_variant"><option value="${variant}">`+(variant==='calf'?'Tríceps + panturrilha medial':'Tríceps + subescapular')+`</option><option value="${variant==='calf'?'subscapular':'calf'}">${variant==='calf'?'Tríceps + subescapular':'Tríceps + panturrilha medial'}</option></select></div>`:'';
    const extra=key==='slaughter'?`<div class="field"><label>Estágio maturacional informado pelo profissional</label><select class="input" name="maturation"><option value="">Selecionar</option><option value="pre">Pré-púbere (Tanner I–II)</option><option value="pub">Púbere (Tanner III)</option><option value="post">Pós-púbere (Tanner IV–V)</option></select></div><div class="field"><label>Categoria da amostra original (meninos, ramo ≤35 mm)</label><select class="input" name="slaughter_group"><option value="">Não informada</option><option value="white">Branco (tabela original)</option><option value="black">Negro (tabela original)</option></select></div>`:'';
    host.innerHTML=prefix+extra+sites.map((s,i)=>`<div class="field"><label>${esc(s)} (mm)</label><input class="input skinfold" name="fold_${i}" data-site="${esc(s)}" type="number" step="0.1" min="0" placeholder="mm"></div>`).join('')+`<div class="field"><label>Protocolo de medida</label><select class="input" name="fold_side"><option>Direito</option><option>Esquerdo</option></select></div>`;
    if(key==='slaughter')form.elements.slaughter_variant.onchange=drawSites;
    $$('[name=maturation],[name=slaughter_group]',host).forEach(x=>x.onchange=()=>calculateProtocol(key,sites));
    $$('.skinfold',host).forEach(x=>x.oninput=()=>calculateProtocol(key,sites));calculateProtocol(key,sites);
  };
  const age=currentClient.birth_date?ageOn(currentClient.birth_date,$('#eval-date').value):null;
  const note=key==='guedes'?`${def.note} Cálculo suspenso até revisão final dos coeficientes contra o original.`:key==='slaughter'?`${def.note} Informe estágio maturacional; para meninos com TR+SE ≤35 mm, selecione também a categoria usada pela tabela original.`:def.note;
  $('#protocol-note').textContent=`${note}${age!==null?` Idade na avaliação: ${age} anos.`:''}`;
  drawSites();
}
function calculateProtocol(key,sites){
  const form=$('#evaluation-form'), vals=$$('.skinfold',form).map(x=>parseFloat(x.value)), ready=vals.length===sites.length&&vals.every(x=>Number.isFinite(x)&&x>0), out=$('#fat-result');
  if(!ready){out.hidden=true;protocolResult=null;return}
  const S=vals.reduce((a,b)=>a+b,0), age=currentClient.birth_date?ageOn(currentClient.birth_date,$('#eval-date').value):null, sex=currentClient.sex, log=x=>Math.log10(x);
  let D=null,pct=null,label='',details={};
  const densityToPercent=d=>495/d-450, conversionName='conversão padrão';
  if(key==='isak8')label=`Σ8 = ${S.toFixed(1)} mm · não representa % de gordura`;
  else if(key==='jp7'&&age!==null&&['Masculino','Feminino'].includes(sex)){D=sex==='Masculino'?1.112-.00043499*S+.00000055*S*S-.00028826*age:1.097-.00046971*S+.00000056*S*S-.00012828*age;label=`Densidade corporal ${D.toFixed(4)} g/cm³ · ${conversionName}`;pct=densityToPercent(D)}
  else if(key==='petroski'&&age!==null&&sex==='Masculino'&&age>=18&&age<=66){D=1.10726863-.00081201*S+.00000212*S*S-.00041761*age;pct=densityToPercent(D);label=`Petroski homens · densidade corporal ${D.toFixed(4)} g/cm³ · ${conversionName}`}
  else if(key==='petroski'&&age!==null&&sex==='Feminino'&&age>=18&&age<=51){D=1.1954713-.07513507*log(S)-.00041072*age;pct=densityToPercent(D);label=`Petroski mulheres · densidade corporal ${D.toFixed(4)} g/cm³ · ${conversionName}`}
  else if(key==='guedes'){label='Guedes: coleta e soma registradas; percentual suspenso até revisão final da transcrição original.'}
  else if(key==='dw'&&age!==null&&age>=17&&['Masculino','Feminino'].includes(sex)){const ranges=sex==='Masculino'?[[17,19,1.162,.063],[20,29,1.1631,.0632],[30,39,1.1422,.0544],[40,49,1.162,.07],[50,130,1.1715,.0779]]:[[17,19,1.1549,.0678],[20,29,1.1599,.0717],[30,39,1.1423,.0632],[40,49,1.1333,.0612],[50,130,1.1339,.0645]];const r=ranges.find(x=>age>=x[0]&&age<=x[1]);if(r){D=r[2]-r[3]*log(S);pct=densityToPercent(D);label=`Durnin & Womersley · densidade corporal ${D.toFixed(4)} g/cm³ · ${conversionName}`}}
  else if(key==='yuhasz'&&['Masculino','Feminino'].includes(sex)){pct=sex==='Masculino'?.1051*S+2.585:.1548*S+3.58;label='Yuhasz/Carter · % direto · versão atleta'}
  else if(key==='faulkner'&&sex==='Masculino'){pct=.153*S+5.783;label='Faulkner · % direto · versão histórica atleta masculino'}
  else if(key==='faulkner'){label='Faulkner: a versão documentada é histórica e voltada principalmente a homens atletas; não estimar para esta seleção.'}
  else if(key==='slaughter'){
    const variant=form.elements.slaughter_variant?.value||'subscapular', maturation=form.elements.maturation?.value||'', group=form.elements.slaughter_group?.value||'';details={variant,maturation,group};
    if(variant==='calf'){pct=sex==='Masculino'?.735*S+1:.610*S+5.1;label='Slaughter TR+panturrilha · estimativa direta; faixa e amostra conforme protocolo'}
    else if(S>35&&['Masculino','Feminino'].includes(sex)){pct=sex==='Masculino'?.783*S+1.6:.546*S+9.7;label='Slaughter TR+SE, Σ>35 mm · estimativa direta'}
    else if(sex==='Feminino'&&S<=35){pct=1.33*S-.013*S*S-2.5;label='Slaughter meninas TR+SE, Σ≤35 mm · versão −2,5'}
    else if(sex==='Masculino'&&S<=35&&maturation&&group){const constants={white:{pre:1.7,pub:3.4,post:5.5},black:{pre:3.2,pub:5.2,post:6.8}};pct=1.21*S-.008*S*S-constants[group][maturation];label='Slaughter meninos TR+SE, Σ≤35 mm · estágio e categoria registrados'}
    else label='Slaughter: informe sexo, estágio maturacional e categoria da tabela original quando exigidos.';
  }
  else label='Informe data de nascimento e sexo usados pela equação; fora da faixa, não estimar.';
  const validPct=Number.isFinite(pct)&&pct>=0&&pct<=75?pct:null,result=pct===null?`Σ ${S.toFixed(1)} mm`:validPct!==null?`${validPct.toFixed(1)}%`:'fora do intervalo esperado';$('#fat-label').textContent=label;$('#fat-value').textContent=result;out.hidden=false;protocolResult={protocol:key,sum:S,bodyDensity:D,bodyFatPercent:validPct,sites,values:vals,conversion:'Siri',details,eligibility:label};
}
function postureSection(){return `<section class="panel module-section"><div class="small-caps">MÓDULO 02</div><div class="panel-title" style="margin:4px 0 8px">Avaliação postural</div><div class="notice">As linhas e marcações são referências visuais para o avaliador. Elas não detectam pontos automaticamente nem produzem diagnóstico. Fotos são opcionais.</div><div class="subheading">Fotos por vista e simetrógrafo</div><p class="help">Adicione cada foto no campo da vista correspondente. A grade vermelha aparece sobre a imagem e pode ser ligada ou desligada. Ative a marcação: dois cliques formam uma linha D–E e mostram seu ângulo em graus. Nas vistas frontal/posterior há segmentos de ombros, escápulas, pelve e cabeça (tragion). Na lateral, selecione tragion–tornozelo para medir o desvio da vertical.</p>${views.map(view=>`<div class="module-section posture-view-card"><div class="page-row" style="justify-content:space-between"><strong style="font-size:12px">${esc(view)}</strong><span class="badge">Foto, grade e marcações</span></div><label class="photo-input posture-upload">Foto da vista ${esc(view.toLowerCase())}<input type="file" name="posturePhoto_${esc(view)}" data-posture-photo="${esc(view)}" accept="image/*" capture="environment" style="display:block;margin-top:8px;font-size:10px"></label><div class="posture-photo-stage" data-posture-stage="${esc(view)}"><div class="posture-empty">Adicione uma foto para ativar o simetrógrafo e as marcações.</div></div><div class="posture-tools"><button class="button button-secondary button-sm" type="button" data-grid-toggle="${esc(view)}" aria-pressed="true">Simetrógrafo ligado</button><label class="check-row posture-mark-mode"><input type="checkbox" data-point-mode="${esc(view)}"><span>Marcar pontos anatômicos</span></label><select class="input" data-landmark-pair="${esc(view)}" aria-label="Par de pontos anatômicos — ${esc(view)}">${(landmarkPairs[view]||[]).map(x=>`<option>${esc(x)}</option>`).join('')}</select><button class="button button-secondary button-sm" type="button" data-undo-mark="${esc(view)}">Desfazer ponto</button><button class="button button-secondary button-sm" type="button" data-clear-marks="${esc(view)}">Limpar pontos</button></div><small class="help" data-mark-status="${esc(view)}">Clique uma vez no ponto D e outra no ponto E. A linha e o ângulo aparecem na foto.</small><div class="check-grid" style="margin-top:9px">${(posturalFindings[view]||[]).map(f=>`<label class="check-row"><input type="checkbox" name="posture_${esc(view)}" value="${esc(f)}"><span>${esc(f)}</span></label>`).join('')}</div><textarea class="input" name="posture_note_${esc(view)}" rows="2" style="width:100%;margin-top:8px" placeholder="Observação livre da vista ${view.toLowerCase()}…"></textarea></div>`).join('')}<div class="form-grid" style="margin-top:14px"><div class="field"><label>Escoliómetro — ângulo de rotação do tronco (opcional)</label><input class="input" name="scoliometer" type="number" step="0.1" placeholder="graus"></div><div class="field"><label>Região/lado do escoliómetro</label><input class="input" name="scoliometer_region" placeholder="Ex.: torácica, lado convexo"></div><div class="field"><label>Goniometria / amplitude articular (opcional)</label><input class="input" name="rom_note" placeholder="Articulação, movimento, lado"></div><div class="field"><label>Amplitude medida</label><input class="input" name="rom_degrees" type="number" step="1" placeholder="graus"></div></div><div class="field" style="margin-top:12px"><label>Conclusão postural do avaliador</label><textarea class="input" name="posture_conclusion" rows="3" placeholder="Síntese profissional para o relatório…"></textarea></div></section>`}
function landmarkAngle(mark,view,ratio=1){const d=mark.right||mark.point1,e=mark.left||mark.point2;if(!d||!e)return null;const dx=e.x-d.x,dy=(e.y-d.y)*ratio;let angle;if((view.startsWith('Lateral')&&/tragion ao tornozelo/i.test(mark.pair||'')))angle=Math.atan2(dx,dy)*180/Math.PI;else{angle=Math.atan2(dy,dx)*180/Math.PI;if(angle>90)angle-=180;if(angle< -90)angle+=180}return angle}
function landmarkOverlay(view,marks=[],gridOn=true,ratio=1){const h=1000*Math.max(.25,Math.min(3,ratio)),grid=gridOn?`<div class="posture-grid-overlay" aria-hidden="true"></div>`:'';const points=marks.map(m=>{const pairLabel=esc(m.pair),a=m.right||m.point1,b=m.left||m.point2,vertical=view.startsWith('Lateral')&&/tragion ao tornozelo/i.test(m.pair||''),angle=landmarkAngle(m,view,ratio),labelA=vertical?'T':'D',labelB=vertical?'A':'E',ref=vertical?(a&&b?`<line x1="${(a.x+b.x)*500}" y1="0" x2="${(a.x+b.x)*500}" y2="${h}" class="landmark-level"/>`:''):(a&&b?`<line x1="0" y1="${(a.y+b.y)*h/2}" x2="1000" y2="${(a.y+b.y)*h/2}" class="landmark-level"/>`:'');return `${ref}${a&&b?`<line x1="${a.x*1000}" y1="${a.y*h}" x2="${b.x*1000}" y2="${b.y*h}" class="landmark-link"/>`:''}${a?`<circle cx="${a.x*1000}" cy="${a.y*h}" r="11" class="landmark-dot"/><text x="${a.x*1000+14}" y="${a.y*h-12}" class="landmark-label">${labelA}</text>`:''}${b?`<circle cx="${b.x*1000}" cy="${b.y*h}" r="11" class="landmark-dot"/><text x="${b.x*1000+14}" y="${b.y*h-12}" class="landmark-label">${labelB}</text>`:''}${a&&b&&angle!==null?`<text x="${(a.x+b.x)*500+12}" y="${(a.y+b.y)*h/2-12}" class="landmark-angle">${angle>0?'+':''}${angle.toFixed(1)}°</text>`:''}<title>${pairLabel}${angle!==null?` — ${angle.toFixed(1)} graus`:''}</title>`}).join('');return `${grid}<svg class="landmark-svg" viewBox="0 0 1000 ${h}" preserveAspectRatio="none" aria-label="Pontos D/E e ângulos da vista ${esc(view)}">${points}</svg>`}
function redrawPostureView(view){const stage=$(`[data-posture-stage="${CSS.escape(view)}"]`);if(!stage)return;const img=stage.querySelector('img');if(!img)return;const ratio=posturePhotoDims[view]?.ratio||1;const on=postureGridState[view]!==false;stage.classList.toggle('grid-off',!on);stage.querySelector('.posture-overlay')?.remove();const overlay=document.createElement('div');overlay.className='posture-overlay';overlay.innerHTML=landmarkOverlay(view,postureMarkers[view]||[],on,ratio);stage.append(overlay);const b=$(`[data-grid-toggle="${CSS.escape(view)}"]`);if(b){b.textContent=on?'Simetrógrafo ligado':'Simetrógrafo desligado';b.setAttribute('aria-pressed',String(on))}const marks=postureMarkers[view]||[],status=$(`[data-mark-status="${CSS.escape(view)}"]`),complete=marks.filter(m=>m.right&&m.left),angles=complete.map(m=>`${m.pair}: ${landmarkAngle(m,view,ratio).toFixed(1)}°`);if(status)status.textContent=complete.length?`Marcas D/E: ${angles.join(' · ')}${marks.length>complete.length?' · próximo ponto: '+(marks.at(-1)?.right?'E':'D'):''}`:`Clique no ponto D e depois no ponto E. ${marks.length?'Primeiro ponto marcado; clique no segundo para traçar e medir.':''}`}
function wirePhotos(){
  const inputs=$$('[data-posture-photo]');
  inputs.forEach(inp=>{inp.onchange=()=>{const view=inp.dataset.posturePhoto,file=inp.files?.[0],stage=$(`[data-posture-stage="${CSS.escape(view)}"]`);if(!file||!stage)return;const url=URL.createObjectURL(file);stage.innerHTML=`<img alt="Foto postural — ${esc(view)}" src="${url}"><div class="posture-overlay"></div>`;const img=stage.querySelector('img');img.onload=()=>{posturePhotoDims[view]={width:img.naturalWidth,height:img.naturalHeight,ratio:img.naturalHeight/img.naturalWidth};stage.style.aspectRatio=`${img.naturalWidth} / ${img.naturalHeight}`;redrawPostureView(view)};postureGridState[view]=true;postureMarkers[view]=[];redrawPostureView(view)}});
  $$('[data-grid-toggle]').forEach(b=>b.onclick=()=>{const v=b.dataset.gridToggle;postureGridState[v]=postureGridState[v]===false;redrawPostureView(v)});
  $$('[data-point-mode]').forEach(c=>c.onchange=()=>{const stage=$(`[data-posture-stage="${CSS.escape(c.dataset.pointMode)}"]`);if(stage)stage.classList.toggle('marking',c.checked)});
  $$('[data-posture-stage]').forEach(stage=>stage.onclick=e=>{const view=stage.dataset.postureStage;if(!stage.classList.contains('marking')||!stage.querySelector('img'))return;const img=stage.querySelector('img'),r=img.getBoundingClientRect(),x=Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y=Math.max(0,Math.min(1,(e.clientY-r.top)/r.height)),pair=$(`[data-landmark-pair="${CSS.escape(view)}"]`)?.value||'Livre — D/E',arr=postureMarkers[view]||[];let mark=arr.find(m=>m.pair===pair&&(!m.right||!m.left));if(!mark){mark={pair,right:null,left:null};arr.push(mark)}const side=mark.right?'left':'right';mark[side]={x,y};postureLastPoint[view]={pair,side};postureMarkers[view]=arr;redrawPostureView(view)});
  $$('[data-undo-mark]').forEach(b=>b.onclick=()=>{const view=b.dataset.undoMark,arr=postureMarkers[view]||[],last=arr.at(-1);if(last?.left)last.left=null;else if(last?.right)arr.pop();redrawPostureView(view)});
  $$('[data-clear-marks]').forEach(b=>b.onclick=()=>{postureMarkers[b.dataset.clearMarks]=[];postureLastPoint[b.dataset.clearMarks]=null;redrawPostureView(b.dataset.clearMarks)});
}function physicalSection(){return `<section class="panel module-section"><div class="small-caps">MÓDULO 03</div><div class="panel-title" style="margin:4px 0 8px">Testes físicos e funcionais</div><div class="notice notice-green">Marque os testes realizados. Se o equipamento não estiver disponível, deixe desmarcado e continue a avaliação.</div><div class="subheading">Força, potência e capacidade aeróbica</div><div class="test-list">${tests.map(t=>testCard(t)).join('')}</div><div class="subheading">Testes clínicos e funcionais por segmento</div><p class="help">Registre lado, sintoma conhecido, intensidade e resultado. Um teste isolado não determina diagnóstico.</p><div class="test-list">${clinical.map(t=>testCard(t)).join('')}</div><div class="field" style="margin-top:15px"><label>Observação geral dos testes</label><textarea class="input" name="physical_notes" rows="2" placeholder="Contexto, intercorrências ou notas do avaliador…"></textarea></div></section>`}
function testCard(t){return `<label class="test-card"><input type="checkbox" name="test_${t.id}" value="yes"><span><strong>${esc(t.name)}</strong><p><b>${esc(t.group)}</b> · ${esc(t.how)}</p></span><span class="test-input"><select class="input" name="result_${t.id}"><option value="">Resultado</option><option>Positivo</option><option>Negativo</option><option>Inconclusivo</option><option>Não realizado</option></select><select class="input" name="side_${t.id}" style="width:100%;margin-top:5px"><option selected>Direito</option><option>Esquerdo</option><option>Ambos</option></select><input class="input" name="value_${t.id}" placeholder="${esc(t.unit)}" style="width:100%;margin-top:5px"><input class="input" name="pain_${t.id}" type="number" min="0" max="10" placeholder="Dor 0–10 (opcional)" style="width:100%;margin-top:5px"></span></label>`}
